import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from "../examples/link-demo";

const Example = () => <Demo />;

export default Example;
";

const meta = {
  parameters: {
    docs: { description: { component: "## Usage

`Link` is TanStack Router's `Link` with one addition: it preloads its route when the user is about to use it, not only once they hover it. Use it for every in-app link.

**Import:** `@/registry/erbium/ui/link`

```tsx
import { Link } from "@/registry/erbium/ui/link";

<Link to="/projects/$projectId" params={{ projectId }}>
  Open project
</Link>;
```

The props and types are Router's own. Routes, params, search, hash, masks, `activeProps`, and `activeOptions` are checked against your route tree exactly as they are for Router's `Link`, so switching an import changes nothing else.

## How it works

Router's `intent` preload starts when the pointer enters the link, after a short delay. By then the user is usually a few hundred milliseconds from clicking, and a slow loader is still running when the click arrives.

`Link` also preloads when the user is heading for it:

- The cursor's path points at the link.
- The link is one or two tab stops ahead of the focused element.
- Scrolling is bringing the link under the cursor.
- A finger touches the link.

Prediction comes from [ForesightJS](https://foresightjs.com), through the same `usePredictedIntent` hook the library exposes. The preload runs the route's loaders, so data, code-split route components, and anything a loader starts are ready together. Router's own hover and focus preloading stays on as a fallback, and the router reuses the cached result when both fire.

Prediction turns itself off on slow connections and when the browser asks to save data.

## Composition

Components that take a link through `render` work with `Link` unchanged:

```tsx
<SidebarMenuButton render={<Link to="/inbox" />} isActive={pathname === "/inbox"}>
  Inbox
</SidebarMenuButton>

<BreadcrumbLink render={<Link to="/projects" />}>Projects</BreadcrumbLink>

<NavigationMenuLink render={<Link to="/docs" />} className={navigationMenuTriggerStyle()}>
  Documentation
</NavigationMenuLink>

<Item render={<Link to="/settings/billing" />}>
  <ItemContent>
    <ItemTitle>Billing</ItemTitle>
  </ItemContent>
</Item>
```

For a link styled as a button, put `buttonVariants` on `Link` rather than rendering a `Button` as a link:

```tsx
<Link to="/projects/new" className={buttonVariants({ variant: "outline" })}>
  New project
</Link>
```

## Router configuration

`Link` reads the router's preload settings. A router configured like this gets the most from it:

```tsx
createRouter({
  routeTree,
  defaultPreload: "intent",
  // How long a preloaded match stays fresh. Match it to how fast your data changes.
  defaultPreloadStaleTime: 30_000,
});
```

A preloaded link predicts again once its match would be stale or collected, so a link that stays on screen keeps its route warm.

## Opting out

`Link` follows Router's preload rules:

- `preload={false}` turns prediction off along with Router's own preloading. Use it for links to expensive or side-effecting routes.
- Disabled links, `reloadDocument` links, and external URLs never predict.
- A router created with `defaultPreload: false` turns prediction off for every link that does not opt back in.

Links outside the app, such as an `https:` URL in a footer, can still use `Link`; Router renders them as plain anchors." } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Components/Link",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "Each page in this example takes 900 ms to load. Move toward a page link and click it: the page reports whether it was ready before the click or how long you waited. Reset, turn prediction off, and try again to compare with Router's hover preloading alone." },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/link-demo";

const Example = () => <Demo />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <OverlayProvider>
      {children}
      {toast && <Toaster />}
    </OverlayProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);
